public class Note { public string id{get;set;} public string title{get;set;} public string todo{get;set;} public string category{get;set;} public string due{get;set;} public string reminderAt{get;set;} public string reminderSnoozedUntil{get;set;} public string reminderFiredFor{get;set;} public string reminderDismissedFor{get;set;} public string paper{get;set;} public string fastener{get;set;} public double x{get;set;} public double y{get;set;} public double rotation{get;set;} public int z{get;set;} public string created{get;set;} public string updated{get;set;} public string completed{get;set;} public int revision{get;set;} public int syncedRevision{get;set;} }
public class BoardSettings {public string theme{get;set;} public bool onboarded{get;set;} public string installationId{get;set;} public string lastSyncAccount{get;set;} public int tossCount{get;set;} public bool muted{get;set;} public double paperScale{get;set;} public string reminderVoice{get;set;} public double? reminderVolume{get;set;} public bool remindersMuted{get;set;} }
public class BoardState {public List<Note> notes{get;set;} public BoardSettings settings{get;set;} public BoardState(){notes=new List<Note>();settings=new BoardSettings{theme="garden",installationId=Guid.NewGuid().ToString("N")};}}
public class GoogleIdentity {public string client_id{get;set;} public string client_secret{get;set;} }
public class TokenState {public string refreshToken{get;set;} public string accessToken{get;set;} public DateTime expires{get;set;} public string spreadsheetId{get;set;} public int sheetId{get;set;} public string email{get;set;} public string lastSync{get;set;} public bool? driveAccess{get;set;} }
public static class Data {
 public static readonly string Root=Program.TestRoot??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"NoteNest");
 public static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=16777216};
 public static string Serialize(object x){return Json.Serialize(x);} public static T Parse<T>(string s){return Json.Deserialize<T>(s);}
 public static void Atomic(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".new";byte[] bytes=new UTF8Encoding(false).GetBytes(text);using(var stream=new FileStream(temp,FileMode.Create,FileAccess.Write,FileShare.None)){stream.Write(bytes,0,bytes.Length);stream.Flush(true);}if(File.Exists(path))File.Replace(temp,path,path+".previous",true);else File.Move(temp,path);}
 public static BoardState Load(){Directory.CreateDirectory(Root);string path=Path.Combine(Root,"board.json");if(!File.Exists(path))return new BoardState();try{return Validate(Parse<BoardState>(File.ReadAllText(path)));}catch{if(File.Exists(path+".previous")){var b=Validate(Parse<BoardState>(File.ReadAllText(path+".previous")));File.Copy(path,path+".recovery-"+DateTime.UtcNow.ToString("yyyyMMddHHmmss"),false);return b;}throw new Exception("Your saved board needs recovery. Existing files were kept in "+Root);}}
 public static BoardState Validate(BoardState b){if(b==null||b.notes==null||b.settings==null||b.notes.Count>10000)throw new Exception("Invalid board data.");var ids=new HashSet<string>();foreach(var n in b.notes){Guid g;if(n==null||!Guid.TryParse(n.id,out g)||!ids.Add(n.id))throw new Exception("Invalid or repeated note identity.");n.title=n.title??"";n.todo=n.todo??"";n.category=n.category??"";n.due=n.due??"";if(n.title.Length>180||n.todo.Length>12000||n.category.Length>80)throw new Exception("Note length exceeds the supported limit.");DateTime dt;if(!DateTime.TryParse(n.created,out dt)||!DateTime.TryParse(n.updated,out dt))throw new Exception("Invalid note timestamp.");n.x=Math.Max(0,Math.Min(1,double.IsNaN(n.x)?0:n.x));n.y=Math.Max(0,Math.Min(1,double.IsNaN(n.y)?0:n.y));n.rotation=Math.Max(-12,Math.Min(12,n.rotation));n.revision=Math.Max(1,n.revision);n.syncedRevision=Math.Max(0,Math.Min(n.revision,n.syncedRevision));}if(string.IsNullOrEmpty(b.settings.installationId))b.settings.installationId=Guid.NewGuid().ToString("N");return b;}
 public static void Save(BoardState b){Atomic(Path.Combine(Root,"board.json"),Serialize(Validate(b)));}
 public static void Protect(string filename,object value){var bytes=Encoding.UTF8.GetBytes(Serialize(value));var secured=ProtectedData.Protect(bytes,null,DataProtectionScope.CurrentUser);Atomic(Path.Combine(Root,filename),Convert.ToBase64String(secured));}
 public static T Unprotect<T>(string filename){var path=Path.Combine(Root,filename);if(!File.Exists(path))return default(T);var bytes=ProtectedData.Unprotect(Convert.FromBase64String(File.ReadAllText(path)),null,DataProtectionScope.CurrentUser);return Parse<T>(Encoding.UTF8.GetString(bytes));}
 public static double Serial(string iso){DateTime date;if(!DateTime.TryParse(iso,System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.RoundtripKind,out date))return 0;return (date.ToUniversalTime()-new DateTime(1899,12,30,0,0,0,DateTimeKind.Utc)).TotalDays;}
 public static object[] Array(object value){var a=value as object[];if(a!=null)return a;var b=value as System.Collections.IEnumerable;return b==null?new object[0]:b.Cast<object>().ToArray();}
 public static Dictionary<string,object> Map(object o){return o as Dictionary<string,object>??new Dictionary<string,object>();} public static string Str(Dictionary<string,object> d,string k){object v;return d.TryGetValue(k,out v)?Convert.ToString(v):"";}
}
