 async Task<Dictionary<string,object>> Request(HttpMethod method,string url,object payload){if(!(url.StartsWith("https://sheets.googleapis.com/v4/spreadsheets")||url.StartsWith("https://www.googleapis.com/drive/v3/files")||url=="https://openidconnect.googleapis.com/v1/userinfo"))throw new Exception("Unsupported Google endpoint.");using(var req=new HttpRequestMessage(method,url)){req.Headers.Authorization=new AuthenticationHeaderValue("Bearer",await Access());if(payload!=null)req.Content=new StringContent(Data.Serialize(payload),Encoding.UTF8,"application/json");using(var r=await http.SendAsync(req)){string text=await r.Content.ReadAsStringAsync();if(!r.IsSuccessStatusCode){if(r.StatusCode==HttpStatusCode.Unauthorized)Tokens.expires=DateTime.MinValue;if((int)r.StatusCode==403&&text.IndexOf("insufficient authentication scopes",StringComparison.OrdinalIgnoreCase)>=0)throw new Exception("Google Drive permission was not granted. Reconnect and tick the Drive files permission checkbox before continuing.");throw new Exception("Google Sheets HTTP "+(int)r.StatusCode+". Your local notes are safe; check the connection and try sync again.");}return string.IsNullOrEmpty(text)?new Dictionary<string,object>():Data.Parse<Dictionary<string,object>>(text);}}}
