 public async Task EnsureSheet(string installation){if(!string.IsNullOrEmpty(Tokens.spreadsheetId))return;string q="trashed = false and appProperties has { key='notenestArchive' and value='"+installation+"' }";var found=await Request(HttpMethod.Get,"https://www.googleapis.com/drive/v3/files?q="+Uri.EscapeDataString(q)+"&fields=files(id,name)&pageSize=10",null);var files=found.ContainsKey("files")?Data.Array(found["files"]):new object[0];string id;if(files.Length>0)id=Data.Str(Data.Map(files[0]),"id");else{var created=await Request(HttpMethod.Post,"https://www.googleapis.com/drive/v3/files?fields=id",new {name="NoteNest — Task Archive",mimeType="application/vnd.google-apps.spreadsheet",appProperties=new Dictionary<string,string>{{"notenestArchive",installation}}});id=Data.Str(created,"id");}
