 public static object[] Formats(int sid){var range=new {sheetId=sid,startRowIndex=1,endColumnIndex=9};var all=new {sheetId=sid,startColumnIndex=0,endColumnIndex=9};var req=new List<object>();req.Add(new {updateSheetProperties=new {properties=new {sheetId=sid,title="Notes",gridProperties=new {rowCount=5000,columnCount=9,frozenRowCount=1,hideGridlines=true}},fields="title,gridProperties"}});req.Add(new {updateSpreadsheetProperties=new {properties=new {locale="en_GB",timeZone="Etc/UTC"},fields="locale,timeZone"}});req.Add(new {updateCells=new {start=new {sheetId=sid,rowIndex=0,columnIndex=0},rows=new[]{new {values=new[]{"Created (UTC)","Work / client","To do","Category","Due date","Status","Completed (UTC)","Updated (UTC)","Note ID"}.Select(s=>Cell(s)).ToArray()}},fields="userEnteredValue"}});req.Add(new {repeatCell=new {range=all,cell=new {userEnteredFormat=new {textFormat=new {fontFamily="Arial",fontSize=11},verticalAlignment="TOP",wrapStrategy="WRAP"}},fields="userEnteredFormat"}});req.Add(new {repeatCell=new {range=new {sheetId=sid,startRowIndex=0,endRowIndex=1,startColumnIndex=0,endColumnIndex=9},cell=new {userEnteredFormat=new {backgroundColor=new {red=.20,green=.30,blue=.23},textFormat=new {bold=true,foregroundColor=new {red=1,green=1,blue=1}},verticalAlignment="MIDDLE"}},fields="userEnteredFormat"}});req.Add(new {updateDimensionProperties=new {range=new {sheetId=sid,dimension="ROWS",startIndex=0,endIndex=1},properties=new {pixelSize=40},fields="pixelSize"}});for(int col=0;col<9;col++){int width=col==2?420:col==1?230:col==3?160:col==5?100:175;req.Add(new {updateDimensionProperties=new {range=new {sheetId=sid,dimension="COLUMNS",startIndex=col,endIndex=col+1},properties=new {pixelSize=width},fields="pixelSize"}});if(col==0||col==4||col==6||col==7)req.Add(new {repeatCell=new {range=new {sheetId=sid,startRowIndex=1,startColumnIndex=col,endColumnIndex=col+1},cell=new {userEnteredFormat=new {numberFormat=new {type=col==4?"DATE":"DATE_TIME",pattern=col==4?"dd mmm yyyy":"dd mmm yyyy hh:mm"}}},fields="userEnteredFormat.numberFormat"}});}req.Add(new {updateDimensionProperties=new {range=new {sheetId=sid,dimension="COLUMNS",startIndex=8,endIndex=9},properties=new {hiddenByUser=true},fields="hiddenByUser"}});req.Add(new {setBasicFilter=new {filter=new {range=all}}});req.Add(new {setDataValidation=new {range=new {sheetId=sid,startRowIndex=1,startColumnIndex=5,endColumnIndex=6},rule=new {condition=new {type="ONE_OF_LIST",values=new[]{new {userEnteredValue="Open"},new {userEnteredValue="Done"}}},strict=true,showCustomUi=true}}});req.Add(new {addConditionalFormatRule=new {index=0,rule=new {ranges=new[]{range},booleanRule=new {condition=new {type="CUSTOM_FORMULA",values=new[]{new {userEnteredValue="=$F2=\"Open\""}}},format=new {backgroundColor=new {red=.87,green=.94,blue=.85},textFormat=new {foregroundColor=new {red=.16,green=.29,blue=.18}}}}}}});req.Add(new {addConditionalFormatRule=new {index=1,rule=new {ranges=new[]{range},booleanRule=new {condition=new {type="CUSTOM_FORMULA",values=new[]{new {userEnteredValue="=$F2=\"Done\""}}},format=new {backgroundColor=new {red=.91,green=.92,blue=.91},textFormat=new {foregroundColor=new {red=.46,green=.49,blue=.46}}}}}}});return req.ToArray();}
 public async Task<List<Dictionary<string,object>>> Sync(BoardState snapshot){if(!await gate.WaitAsync(0))throw new Exception("Google sync is already running.");try{await EnsureSheet(snapshot.settings.installationId);var pending=snapshot.notes.Where(n=>(!string.IsNullOrWhiteSpace(n.title)||!string.IsNullOrWhiteSpace(n.todo))&&n.revision>n.syncedRevision).ToList();if(pending.Count==0)return new List<Dictionary<string,object>>();var id=Tokens.spreadsheetId;var r=await Request(HttpMethod.Get,"https://sheets.googleapis.com/v4/spreadsheets/"+id+"/values/Notes!A2:I5000",null);var rows=r.ContainsKey("values")?Data.Array(r["values"]):new object[0];var index=new Dictionary<string,int>();for(int i=0;i<rows.Length;i++){var cells=Data.Array(rows[i]);if(cells.Length>=9){string key=Convert.ToString(cells[8]);if(index.ContainsKey(key))throw new Exception("Repeated note IDs were found in your spreadsheet. Sync stopped to preserve the archive.");index[key]=i+1;}}
 var requests=new List<object>();var append=new List<object>();foreach(var n in pending){int row;if(index.TryGetValue(n.id,out row))requests.Add(new {updateCells=new {start=new {sheetId=Tokens.sheetId,rowIndex=row,columnIndex=0},rows=new[]{Row(n)},fields="userEnteredValue"}});else append.Add(Row(n));}if(rows.Length+append.Count>=4998)throw new Exception("This archive has reached its 5,000-row limit. Export or review the archive before adding more notes.");if(append.Count>0)requests.Add(new {appendCells=new {sheetId=Tokens.sheetId,rows=append,fields="userEnteredValue"}});requests.Add(new {sortRange=new {range=new {sheetId=Tokens.sheetId,startRowIndex=1,endRowIndex=Math.Max(2,rows.Length+append.Count+1),startColumnIndex=0,endColumnIndex=9},sortSpecs=new[]{new {dimensionIndex=0,sortOrder="DESCENDING"}}}});await Request(HttpMethod.Post,"https://sheets.googleapis.com/v4/spreadsheets/"+id+":batchUpdate",new {requests});var verify=await Request(HttpMethod.Get,"https://sheets.googleapis.com/v4/spreadsheets/"+id+"/values/Notes!A2:I5000",null);var verified=new Dictionary<string,object[]>();foreach(var obj in verify.ContainsKey("values")?Data.Array(verify["values"]):new object[0]){var cells=Data.Array(obj);if(cells.Length>=9)verified[Convert.ToString(cells[8])]=cells;}foreach(var n in pending)if(!verified.ContainsKey(n.id)||Convert.ToString(verified[n.id][5])!=(string.IsNullOrEmpty(n.completed)?"Open":"Done")||Convert.ToString(verified[n.id][1])!=n.title||Convert.ToString(verified[n.id][2])!=n.todo||Convert.ToString(verified[n.id][3])!=n.category)throw new Exception("Google did not confirm every note. Local changes remain queued.");Tokens.lastSync=DateTime.UtcNow.ToString("o");Error="";Data.Protect("google-token.dat",Tokens);return pending.Select(n=>new Dictionary<string,object>{{"id",n.id},{"revision",n.revision}}).ToList();}catch(Exception e){Error=e.Message;throw;}finally{gate.Release();}}
 public static bool HasDriveScope(string scope){return !string.IsNullOrEmpty(scope)&&scope.Split(' ').Contains("https://www.googleapis.com/auth/drive.file");}
 public async Task CheckDriveAccess(){try{await Request(HttpMethod.Get,"https://www.googleapis.com/drive/v3/files?pageSize=1&fields=files(id)",null);Tokens.driveAccess=true;Error="";Data.Protect("google-token.dat",Tokens);}catch(Exception e){Error=e.Message;if(Tokens!=null&&e.Message.StartsWith("Google Drive permission was not granted")){Tokens.driveAccess=false;Data.Protect("google-token.dat",Tokens);}throw;}}
 public void Disconnect(){Tokens=null;Error="";string p=Path.Combine(Data.Root,"google-token.dat");foreach(var path in new[]{p,p+".previous"})if(File.Exists(path))File.Delete(path);}
}
public partial class MainWindow:Form {
 readonly System.Windows.Forms.Timer reminderTimer=new System.Windows.Forms.Timer{Interval=10000};readonly WebView2 web=new WebView2();BoardState board;Google google;bool syncing;bool closing;
 public MainWindow(){Text="NoteNest";Width=1440;Height=880;MinimumSize=new Size(1000,650);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(48,44,39);var icon=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"NoteNest.ico");if(File.Exists(icon))Icon=new Icon(icon);web.Dock=DockStyle.Fill;Controls.Add(web);Load+=async(s,e)=>await Init();FormClosing+=CaptureAndClose;FormClosed+=(s,e)=>reminderTimer.Dispose();reminderTimer.Tick+=(s,e)=>{if(web.CoreWebView2!=null&&!closing)web.CoreWebView2.PostWebMessageAsJson(Data.Serialize(new {eventName="reminderTick"}));};}
 async void CaptureAndClose(object sender,FormClosingEventArgs e){if(closing||board==null)return;e.Cancel=true;try{if(web.CoreWebView2!=null){var capture=web.CoreWebView2.ExecuteScriptAsync("typeof store==='object'?JSON.stringify(store):null");if(await Task.WhenAny(capture,Task.Delay(3000))!=capture)throw new Exception("The last edit is still being saved. Please try closing again in a moment.");var raw=await capture;if(raw!="null"){var candidate=Data.Validate(Data.Parse<BoardState>(Data.Parse<string>(raw)));candidate.settings.installationId=board.settings.installationId;candidate.settings.lastSyncAccount=board.settings.lastSyncAccount;foreach(var n in candidate.notes){var old=board.notes.FirstOrDefault(x=>x.id==n.id);n.syncedRevision=old==null?0:Math.Min(n.revision,old.syncedRevision);}board=candidate;}}Data.Save(board);closing=true;Close();}catch(Exception ex){MessageBox.Show(this,ex.Message,"NoteNest — keep this window open",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
 async Task Init(){try{board=Program.SmokeTest?new BoardState():Data.Load();google=new Google();var environment=await CoreWebView2Environment.CreateAsync(null,Path.Combine(Data.Root,"WebView"));await web.EnsureCoreWebView2Async(environment);web.CoreWebView2.SetVirtualHostNameToFolderMapping("notenest.local",Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"app"),CoreWebView2HostResourceAccessKind.DenyCors);web.CoreWebView2.Settings.AreDefaultContextMenusEnabled=false;web.CoreWebView2.Settings.AreDevToolsEnabled=false;web.CoreWebView2.Settings.IsStatusBarEnabled=false;web.CoreWebView2.Settings.IsZoomControlEnabled=false;web.CoreWebView2.NavigationStarting+=(s,e)=>{if(!e.Uri.StartsWith("https://notenest.local/"))e.Cancel=true;};web.CoreWebView2.NewWindowRequested+=(s,e)=>{e.Handled=true;};web.CoreWebView2.PermissionRequested+=(s,e)=>{if(e.PermissionKind==CoreWebView2PermissionKind.Autoplay&&(e.Uri=="https://notenest.local"||e.Uri.StartsWith("https://notenest.local/"))){e.State=CoreWebView2PermissionState.Allow;e.SavesInProfile=false;e.Handled=true;}};web.CoreWebView2.WebMessageReceived+=Message;if(Program.SmokeTest)web.CoreWebView2.NavigationCompleted+=async(s,e)=>await Smoke();if(!Program.SmokeTest)web.CoreWebView2.NavigationCompleted+=async(s,e)=>{if(google.Tokens!=null&&google.Tokens.driveAccess==null){try{await google.CheckDriveAccess();}catch{}web.CoreWebView2.PostWebMessageAsJson(Data.Serialize(new {eventName="cloud",data=google.Status()}));}};web.CoreWebView2.Navigate("https://notenest.local/index.html");if(!Program.SmokeTest)reminderTimer.Start();}catch(Exception e){if(Program.SmokeTest){Directory.CreateDirectory(Path.Combine(Path.GetDirectoryName(Program.TestRoot),"output"));File.WriteAllText(Path.Combine(Path.GetDirectoryName(Program.TestRoot),"output","result.json"),Data.Serialize(new {passed=false,error=e.ToString()}));Close();return;}MessageBox.Show(this,e.Message+"\n\nYour notes are kept in "+Data.Root,"NoteNest",MessageBoxButtons.OK,MessageBoxIcon.Information);Close();}}
 async void Message(object sender,CoreWebView2WebMessageReceivedEventArgs e){int id=0;try{if(!e.Source.StartsWith("https://notenest.local/"))return;var msg=Data.Parse<Dictionary<string,object>>(e.WebMessageAsJson);id=Convert.ToInt32(msg["id"]);var action=Data.Str(msg,"action");var p=Data.Map(msg.ContainsKey("payload")?msg["payload"]:null);object result=null;
 switch(action){case "bootstrap":result=new {store=board,cloud=google.Status()};break;
 case "save":var next=Data.Validate(Data.Parse<BoardState>(Data.Serialize(p["store"])));next.settings.installationId=board.settings.installationId;next.settings.lastSyncAccount=board.settings.lastSyncAccount;foreach(var n in next.notes){var old=board.notes.FirstOrDefault(x=>x.id==n.id);if(old!=null)n.syncedRevision=Math.Min(n.revision,old.syncedRevision);else n.syncedRevision=0;}Data.Save(next);board=next;result=new {ok=true};break;
 case "configure":using(var dialog=new OpenFileDialog{Title="Choose the NoteNest Desktop app Google JSON",Filter="Google application settings (*.json)|*.json"}){if(dialog.ShowDialog(this)!=DialogResult.OK)throw new Exception("No file selected.");var text=File.ReadAllText(dialog.FileName);var dict=Data.Parse<Dictionary<string,object>>(text);if(!dict.ContainsKey("installed"))throw new Exception("Choose a Desktop app OAuth file.");Data.Atomic(Path.Combine(Data.Root,"google-client.json"),text);google.LoadIdentity();result=google.Status();}break;
 case "connect":await google.Connect();bool accountChanged=board.settings.lastSyncAccount!=google.Tokens.email;if(accountChanged)foreach(var n in board.notes)n.syncedRevision=0;board.settings.lastSyncAccount=google.Tokens.email;Data.Save(board);await google.EnsureSheet(board.settings.installationId);result=new {cloud=google.Status(),resetSync=accountChanged};break;
 case "sync":if(syncing)throw new Exception("A sync is already in progress.");syncing=true;try{var snapshot=Data.Parse<BoardState>(Data.Serialize(board));var acks=await google.Sync(snapshot);foreach(var ack in acks){var n=board.notes.FirstOrDefault(x=>x.id==Convert.ToString(ack["id"]));if(n!=null)n.syncedRevision=Math.Max(n.syncedRevision,Math.Min(n.revision,Convert.ToInt32(ack["revision"])));}Data.Save(board);result=new {acks,cloud=google.Status()};}finally{syncing=false;}break;
 case "openSheet":if(google.Tokens==null||string.IsNullOrEmpty(google.Tokens.spreadsheetId))throw new Exception("Connect Google Sheets first.");Process.Start(new ProcessStartInfo("https://docs.google.com/spreadsheets/d/"+Uri.EscapeDataString(google.Tokens.spreadsheetId)+"/edit"){UseShellExecute=true});result=new {ok=true};break;
 case "disconnect":google.Disconnect();Data.Save(board);result=google.Status();break;
 case "export":using(var d=new SaveFileDialog{Title="Export your NoteNest local backup",Filter="NoteNest backup (*.json)|*.json",FileName="NoteNest-backup-"+DateTime.Now.ToString("yyyy-MM-dd")+".json"}){if(d.ShowDialog(this)!=DialogResult.OK)throw new Exception("Export cancelled.");File.WriteAllText(d.FileName,Data.Serialize(board),new UTF8Encoding(false));}result=new {ok=true};break;
 default:throw new Exception("Unknown NoteNest action.");}Reply(id,result,null);
 }catch(Exception ex){Reply(id,null,ex.Message);}}
 void Reply(int id,object result,string error){if(web.CoreWebView2!=null)web.CoreWebView2.PostWebMessageAsJson(Data.Serialize(new {id,data=result,error}));}
}
public static class Program {
 public static string TestRoot; public static bool SmokeTest;
 [STAThread]public static int Main(string[] args){if(args.Contains("--selftest"))return SelfTest();if(args.Contains("--check-google-access")){try{new Google().CheckDriveAccess().GetAwaiter().GetResult();Console.WriteLine("{\"ok\":true}");return 0;}catch(Exception e){Console.WriteLine(Data.Serialize(new {ok=false,error=e.Message}));return 1;}}if(args.Contains("--connection-status")){Console.WriteLine(Data.Serialize(new Google().Status()));return 0;}if(args.Contains("--smoke")){SmokeTest=true;TestRoot=Path.Combine(Path.GetTempPath(),"NoteNest-Smoke","data");}bool first;using(var mutex=new Mutex(true,"Local\\NoteNest-"+(SmokeTest?"Smoke-":"")+Environment.UserName,out first)){if(!first){MessageBox.Show("NoteNest is already open. Use its existing window.","NoteNest");return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new MainWindow());return 0;}}
 static int SelfTest(){try{var n=new Note{id=Guid.NewGuid().ToString(),title="=SUM(1,2)",todo="A real note",category="Work",created="2026-11-06T12:00:00Z",updated="2026-11-06T12:00:00Z",revision=2,syncedRevision=1,x=2,y=-2,reminderAt="2026-11-07T15:00:00Z",reminderSnoozedUntil="2026-11-07T15:10:00Z",reminderFiredFor="2026-11-07T15:00:00Z",reminderDismissedFor=""};var b=new BoardState();b.notes.Add(n);Data.Validate(b);if(n.x!=1||n.y!=0)throw new Exception("Coordinate clamp failed.");if(Data.Serial("2026-11-06T12:00:00Z")<=40000)throw new Exception("Date conversion failed.");var round=Data.Parse<BoardState>(Data.Serialize(b));if(round.notes[0].reminderAt!=n.reminderAt||round.notes[0].reminderSnoozedUntil!=n.reminderSnoozedUntil||round.notes[0].reminderFiredFor!=n.reminderFiredFor)throw new Exception("Reminder fields lost in native roundtrip.");if(round.notes[0].title!=n.title)throw new Exception("Lossless note serialization failed.");var formats=Data.Serialize(Google.Formats(0));if(!formats.Contains("Open")||!formats.Contains("Done")||!formats.Contains("hiddenByUser"))throw new Exception("Archive format failed.");if(Google.HasDriveScope("openid email")||!Google.HasDriveScope("openid https://www.googleapis.com/auth/drive.file"))throw new Exception("Drive scope gate failed.");Console.WriteLine("PASS: Drive scope gate, identity validation, coordinate clamp, UTC date serial, literal text roundtrip, archive conditional formats");return 0;}catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}
}
}
